350	     */
351	    private void validatePaymentShipmentRequest(PayAndShipmentRequestDto requestDto) {
352	        if (requestDto.getPaymentRequest() == null) {
353	            throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
354	        }
355	
356	        if (requestDto.getReceiverName() == null || requestDto.getReceiverName().trim().isEmpty()) {
357	            throw new InvalidPaymentShipmentDataException("수령인 이름이 없습니다.");
358	        }
359	
360	        if (requestDto.getReceiverPhone() == null || requestDto.getReceiverPhone().trim().isEmpty()) {
361	            throw new InvalidPaymentShipmentDataException("수령인 전화번호가 없습니다.");
362	        }
363	
364	        if (requestDto.getPostalCode() == null || requestDto.getPostalCode().trim().isEmpty()) {
365	            throw new InvalidPaymentShipmentDataException("우편번호가 없습니다.");
366	        }
367	
368	        if (requestDto.getAddress() == null || requestDto.getAddress().trim().isEmpty()) {
369	            throw new InvalidPaymentShipmentDataException("주소가 없습니다.");
370	        }
371	    }
