   343	            notification.put("timestamp", LocalDateTime.now());
   344	            notification.put("retryable", isRetryableError(new RuntimeException(errorMessage)));
   345	
   346	            // 1. 개별 사용자에게 WebSocket 알림
   347	            messagingTemplate.convertAndSendToUser(userEmail, "/queue/notifications", notification);
   348	
   349	            // 2. 주문별 토픽으로 WebSocket 알림
   350	            String orderDestination = "/topic/order/" + orderId;
   351	            messagingTemplate.convertAndSend(orderDestination, notification);
   352	
   353	            log.info("주문 실패 WebSocket 알림 전송 완료: 주문ID={}, 사용자={}", orderId, userEmail);
   354	
   355	            // 3. 실패 알림도 Kafka로 추가 처리 (이메일, SMS 등)
   356	            try {
   357	                Map<String, Object> kafkaNotification = new HashMap<>();
   358	                kafkaNotification.put("type", "ORDER_FAILURE");
   359	                kafkaNotification.put("orderId", orderId);
   360	                kafkaNotification.put("userEmail", userEmail);
   361	                kafkaNotification.put("errorMessage", errorMessage);
   362	                kafkaNotification.put("timestamp", System.currentTimeMillis());
   363	
   364	                notificationKafkaTemplate.send("notification-topic", userEmail, kafkaNotification);
   365	
   366	            } catch (Exception kafkaError) {
   367	                log.warn("Kafka 실패 알림 이벤트 발행 실패: 주문ID={}, 오류={}",
   368	                        orderId, kafkaError.getMessage());
   369	            }
   370	
   371	        } catch (Exception e) {
   372	            log.error("실패 알림 전송 실패: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
   373	        }
   374	    }
